package funcs

import (
	"errors"
	"fmt"
	"net/url"
	"reflect"
	"strconv"
	"strings"
)

// Conv is the conv namespace object. Methods become template functions
// like conv.ToInt64.
type Conv struct{}

func init() {
	RegisterNS("conv", func(deps *Deps) interface{} { return Conv{} })

	c := Conv{}
	RegisterGlobal("default", c.Default)
	RegisterGlobal("join", c.Join)
	RegisterGlobal("urlParse", c.URL)
}

// Default returns def when in is "empty" (zero number, "", false, empty
// array/slice/map, or nil), otherwise in.
func (Conv) Default(def, in interface{}) interface{} {
	if convEmpty(in) {
		return def
	}
	return in
}

func convEmpty(in interface{}) bool {
	if in == nil {
		return true
	}
	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.Bool:
		return !v.Bool()
	case reflect.String, reflect.Array, reflect.Slice, reflect.Map, reflect.Chan:
		return v.Len() == 0
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int() == 0
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return v.Uint() == 0
	case reflect.Float32, reflect.Float64, reflect.Complex64, reflect.Complex128:
		return v.Float() == 0
	}
	return false
}

// Join concatenates the elements of an array or slice with sep between them.
func (c Conv) Join(in interface{}, sep string) (string, error) {
	v := reflect.ValueOf(in)
	if !v.IsValid() || (v.Kind() != reflect.Array && v.Kind() != reflect.Slice) {
		return "", errors.New("input to Join must be an array: expected an array or slice, but got a reflect.Value")
	}
	b := make([]string, v.Len())
	for i := 0; i < v.Len(); i++ {
		b[i] = c.ToString(v.Index(i).Interface())
	}
	return strings.Join(b, sep), nil
}

// URL parses a string as a URL.
func (c Conv) URL(in interface{}) (*url.URL, error) {
	s, ok := in.(string)
	if !ok {
		s = c.ToString(in)
	}
	return url.Parse(s)
}

// ParseInt parses a string as an int64 in the given base and bit size.
func (c Conv) ParseInt(in interface{}, base, bitSize int) (int64, error) {
	s, ok := in.(string)
	if !ok {
		s = c.ToString(in)
	}
	return strconv.ParseInt(s, base, bitSize)
}

