	}
	return strconv.Atoi(s)
}

// ToBool converts the input to a boolean. True values are the number 1 and
// the strings "t", "true" and "yes" (any capitalization).
func (Conv) ToBool(in interface{}) bool {
	if str, ok := in.(string); ok {
		switch strings.ToLower(str) {
		case "t", "true", "yes":
			return true
		}
	}
	f, err := convToFloat64(in)
	return err == nil && f == 1
}

// ToBools converts the inputs to an array of booleans.
func (c Conv) ToBools(in ...interface{}) []bool {
