// ToString converts the input (of any type) to a string.
func (Conv) ToString(in interface{}) string {
	if in == nil {
		return "nil"
	}
	if s, ok := in.(string); ok {
		return s
	}
	return fmt.Sprintf("%v", in)
}

// ToStrings converts the inputs to an array of strings.
func (c Conv) ToStrings(in ...interface{}) []string {
	out := make([]string, len(in))
	for i, v := range in {
		out[i] = c.ToString(v)
	}
	return out
}

func convToInt64(in interface{}) (int64, error) {
	switch v := in.(type) {
	case bool:
		if v {
			return 1, nil
		}
		return 0, nil
	case string:
		s := strings.ReplaceAll(v, ",", "")
		if n, err := strconv.ParseInt(s, 0, 64); err == nil {
			return n, nil
		}
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, fmt.Errorf("could not convert %q to int64: %v", s, err)
		}
		return int64(f), nil
	}

	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return v.Int(), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return int64(v.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return int64(v.Float()), nil
	}
	return 0, fmt.Errorf("could not convert %v to int64", in)
}

func convToFloat64(in interface{}) (float64, error) {
	switch v := in.(type) {
	case bool:
		if v {
			return 1, nil
		}
		return 0, nil
	case string:
		s := strings.ReplaceAll(v, ",", "")
		if n, err := strconv.ParseInt(s, 0, 64); err == nil {
			return float64(n), nil
		}
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, fmt.Errorf("could not convert %q to float64: %v", s, err)
		}
		return f, nil
	}

	v := reflect.ValueOf(in)
	switch v.Kind() {
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		return float64(v.Int()), nil
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
		return float64(v.Uint()), nil
	case reflect.Float32, reflect.Float64:
		return v.Float(), nil
	}
	return 0, fmt.Errorf("could not convert %v to float64", in)
}

package funcs

import (
	"reflect"
	"testing"
)

var c = Conv{}

func TestConvDefault(t *testing.T) {
	cases := []struct {
		def, in, expected interface{}
	}{
		{"x", "", "x"},
		{"x", "y", "y"},
		{"x", 0, "x"},
		{"x", 1, 1},
		{42, 0, 42},
		{"x", 0.0, "x"},
		{"x", false, "x"},
		{"x", true, true},
		{"x", nil, "x"},
		{"x", []interface{}{}, "x"},
		{"x", []interface{}{0}, []interface{}{0}},
		{"x", map[string]interface{}{}, "x"},
		{"x", map[string]interface{}{"a": 0}, map[string]interface{}{"a": 0}},
		{"x", "0", "0"},
	}
	for _, tc := range cases {
		got := c.Default(tc.def, tc.in)
		if !reflect.DeepEqual(got, tc.expected) {
			t.Errorf("Default(%v, %v) = %v, want %v", tc.def, tc.in, got, tc.expected)
		}
	}
}

func TestConvJoin(t *testing.T) {
	got, err := c.Join([]interface{}{1, 2, 3}, "-")
	if err != nil || got != "1-2-3" {
		t.Errorf("Join = %q, %v", got, err)
	}
	got, err = c.Join([]interface{}{1, 2.5, true, "x"}, "-")
	if err != nil || got != "1-2.5-true-x" {
		t.Errorf("Join = %q, %v", got, err)
	}
	got, err = c.Join([]interface{}{}, "-")
	if err != nil || got != "" {
		t.Errorf("Join = %q, %v", got, err)
	}
	got, err = c.Join([]interface{}{nil}, "-")
	if err != nil || got != "nil" {
		t.Errorf("Join = %q, %v", got, err)
	}
	got, err = c.Join([]string{"a", "b"}, "")
	if err != nil || got != "ab" {
		t.Errorf("Join = %q, %v", got, err)
	}
	wantErr := "input to Join must be an array: expected an array or slice, but got a reflect.Value"
	for _, bad := range []interface{}{"foo", 42, nil} {
		_, err = c.Join(bad, "-")
		if err == nil || err.Error() != wantErr {
			t.Errorf("Join(%v) err = %v, want %q", bad, err, wantErr)
		}
	}
}

func TestConvURL(t *testing.T) {
	u, err := c.URL("https://example.com:443/foo/bar")
	if err != nil {
		t.Fatal(err)
	}
	if u.Scheme != "https" || u.Host != "example.com:443" || u.Path != "/foo/bar" {
		t.Errorf("URL parsed wrong: %v", u)
	}
	u, err = c.URL(42)
	if err != nil || u.String() != "42" {
		t.Errorf("URL(42) = %v, %v", u, err)
	}
	_, err = c.URL("://bad")
	if err == nil || err.Error() != `parse "://bad": missing protocol scheme` {
		t.Errorf("URL err = %v", err)
	}
	u, err = c.URL("https://user:supersecret@example.com")
	if err != nil || u.Redacted() != "https://user:xxxxx@example.com" {
		t.Errorf("Redacted = %v, %v", u, err)
	}
}

func TestConvParseInt(t *testing.T) {
	n, err := c.ParseInt("7C0", 16, 32)
	if err != nil || n != 1984 {
		t.Errorf("ParseInt = %d, %v", n, err)
	}
	n, err = c.ParseInt(42, 16, 32)
	if err != nil || n != 66 {
		t.Errorf("ParseInt(42,16,32) = %d, %v", n, err)
	}
	_, err = c.ParseInt("zz", 16, 32)
	if err == nil || err.Error() != `strconv.ParseInt: parsing "zz": invalid syntax` {
		t.Errorf("ParseInt err = %v", err)
	}
	_, err = c.ParseInt("FF", 16, 4)
	if err == nil || err.Error() != `strconv.ParseInt: parsing "FF": value out of range` {
		t.Errorf("ParseInt err = %v", err)
	}
}

func TestConvParseUint(t *testing.T) {
	n, err := c.ParseUint("FFFFFFFFFFFFFFFF", 16, 64)
	if err != nil || n != 18446744073709551615 {
		t.Errorf("ParseUint = %d, %v", n, err)
	}
	_, err = c.ParseUint("zz", 16, 64)
	if err == nil || err.Error() != `strconv.ParseUint: parsing "zz": invalid syntax` {
		t.Errorf("ParseUint err = %v", err)
	}
}

func TestConvParseFloat(t *testing.T) {
	f, err := c.ParseFloat("3.14159", 64)
	if err != nil || f != 3.14159 {
		t.Errorf("ParseFloat = %v, %v", f, err)
	}
	_, err = c.ParseFloat("abc", 64)
	if err == nil || err.Error() != `strconv.ParseFloat: parsing "abc": invalid syntax` {
		t.Errorf("ParseFloat err = %v", err)
	}
}

func TestConvAtoi(t *testing.T) {
	n, err := c.Atoi("42")
	if err != nil || n != 42 {
		t.Errorf("Atoi = %d, %v", n, err)
	}
	n, err = c.Atoi(42)
	if err != nil || n != 42 {
		t.Errorf("Atoi(42) = %d, %v", n, err)
	}
	_, err = c.Atoi("abc")
	if err == nil || err.Error() != `strconv.Atoi: parsing "abc": invalid syntax` {
		t.Errorf("Atoi err = %v", err)
	}
}

func TestConvToBool(t *testing.T) {
	trues := []interface{}{"1", "t", "T", "true", "TRUE", "yes", "YES", "0x01", "01", 1, 1.0, "1.0", "1e0", "0x1", "01.0", true}
	for _, in := range trues {
		if !c.ToBool(in) {
			t.Errorf("ToBool(%v) = false, want true", in)
		}
	}
	falses := []interface{}{"0", "on", "y", "NO", "2", "0x02", 0, 2, -1, 0.5, 1.5, "1.5", "0.5", nil, false, "TRUE ", "1 ", "blah", map[string]int{"a": 1}}
	for _, in := range falses {
		if c.ToBool(in) {
			t.Errorf("ToBool(%v) = true, want false", in)
		}
	}
	got := c.ToBools("yes", true, "0x01")
	if !reflect.DeepEqual(got, []bool{true, true, true}) {
		t.Errorf("ToBools = %v", got)
	}
	if got := c.ToBools(); len(got) != 0 {
		t.Errorf("ToBools() = %v", got)
	}
}

func TestConvToInt64(t *testing.T) {
	cases := []struct {
		in       interface{}
		expected int64
	}{
		{"9223372036854775807", 9223372036854775807},
		{"0x42", 66},
		{true, 1},
		{false, 0},
		{4.7, 4},
		{-4.7, -4},
		{"4.7", 4},
		{"123,456.99", 123456},
		{"1.2345e+3", 1234},
		{"1,2,3", 123},
		{"0b101", 5},
		{"0o17", 15},
		{"017", 15},
		{"1_000", 1000},
		{"08", 8},
		{"0x1p4", 16},
		{"9223372036854775808", -9223372036854775808},
		{42, 42},
	}
	for _, tc := range cases {
		got, err := c.ToInt64(tc.in)
		if err != nil || got != tc.expected {
			t.Errorf("ToInt64(%v) = %d, %v; want %d", tc.in, got, err, tc.expected)
		}
	}
	errCases := []struct {
		in      interface{}
		wantErr string
	}{
		{"abc", `could not convert "abc" to int64: strconv.ParseFloat: parsing "abc": invalid syntax`},
		{nil, "could not convert <nil> to int64"},
		{"12,abc", `could not convert "12abc" to int64: strconv.ParseFloat: parsing "12abc": invalid syntax`},
		{"", `could not convert "" to int64: strconv.ParseFloat: parsing "": invalid syntax`},
		{map[string]int{"a": 1}, "could not convert map[a:1] to int64"},
	}
	for _, tc := range errCases {
		_, err := c.ToInt64(tc.in)
		if err == nil || err.Error() != tc.wantErr {
			t.Errorf("ToInt64(%v) err = %v, want %q", tc.in, err, tc.wantErr)
		}
	}

	n, err := c.ToInt("42")
	if err != nil || n != 42 {
		t.Errorf("ToInt = %d, %v", n, err)
	}
	_, err = c.ToInt("abc")
	if err == nil || err.Error() != `could not convert "abc" to int64: strconv.ParseFloat: parsing "abc": invalid syntax` {
		t.Errorf("ToInt err = %v", err)
	}

	got, err := c.ToInt64s(true, 0x42, "123,456.99", "1.2345e+3")
	if err != nil || !reflect.DeepEqual(got, []int64{1, 66, 123456, 1234}) {
		t.Errorf("ToInt64s = %v, %v", got, err)
	}
	_, err = c.ToInt64s(1, "abc")
	if err == nil {
		t.Error("ToInt64s expected error")
	}
	gi, err := c.ToInts(true, "0x42")
	if err != nil || !reflect.DeepEqual(gi, []int{1, 66}) {
		t.Errorf("ToInts = %v, %v", gi, err)
	}
}

func TestConvToFloat64(t *testing.T) {
	cases := []struct {
		in       interface{}
		expected float64
	}{
		{"8.233e-1", 0.8233},
		{"9,000.09", 9000.09},
		{true, 1},
		{false, 0},
		{4, 4},
		{"0x42", 66},
		{"1_000", 1000},
		{"010", 8},
		{"-1,234.5", -1234.5},
	}
	for _, tc := range cases {
		got, err := c.ToFloat64(tc.in)
		if err != nil || got != tc.expected {
			t.Errorf("ToFloat64(%v) = %v, %v; want %v", tc.in, got, err, tc.expected)
		}
	}
	errCases := []struct {
		in      interface{}
		wantErr string
	}{
		{"abc", `could not convert "abc" to float64: strconv.ParseFloat: parsing "abc": invalid syntax`},
		{nil, "could not convert <nil> to float64"},
		{"", `could not convert "" to float64: strconv.ParseFloat: parsing "": invalid syntax`},
		{map[string]int{"a": 1}, "could not convert map[a:1] to float64"},
	}
	for _, tc := range errCases {
		_, err := c.ToFloat64(tc.in)
		if err == nil || err.Error() != tc.wantErr {
			t.Errorf("ToFloat64(%v) err = %v, want %q", tc.in, err, tc.wantErr)
		}
	}
	got, err := c.ToFloat64s(true, 0x42, "123,456.99", "1.2345e+3")
	if err != nil || !reflect.DeepEqual(got, []float64{1, 66, 123456.99, 1234.5}) {
		t.Errorf("ToFloat64s = %v, %v", got, err)
	}
}

func TestConvToString(t *testing.T) {
	cases := []struct {
		in       interface{}
		expected string
	}{
		{0xFF, "255"},
		{nil, "nil"},
		{true, "true"},
		{"hi", "hi"},
		{4.0, "4"},
		{3.14, "3.14"},
		{1e20, "1e+20"},
		{[]interface{}{1, 2}, "[1 2]"},
		{map[string]int{"b": 1, "a": 2}, "map[a:2 b:1]"},
	}
	for _, tc := range cases {
		if got := c.ToString(tc.in); got != tc.expected {
			t.Errorf("ToString(%v) = %q, want %q", tc.in, got, tc.expected)
