	got := c.ToStrings(nil, 42, true, 0xF, []interface{}{1, 2, 3})
	if !reflect.DeepEqual(got, []string{"nil", "42", "true", "15", "[1 2 3]"}) {
		t.Errorf("ToStrings = %v", got)
	}
	if got := c.ToStrings(); len(got) != 0 {
		t.Errorf("ToStrings() = %v", got)
	}
}

